class Command(BaseCommand):
    help = "Carga las ubicaciones de las dos bodegas (bodega, pasillo/zona, estante/módulo, nivel)."

    def handle(self, *args, **options):
        creadas = 0
        actualizadas = 0
        for bodega, pasillo, estante, nivel, detalle in UBICACIONES:
            ubicacion = Ubicaciones.objects.filter(
                bodega=bodega, pasillo=pasillo, estante=estante, nivel=nivel).first()
            if ubicacion is None:
                Ubicaciones.objects.create(bodega=bodega, pasillo=pasillo, estante=estante,
                                           nivel=nivel, detalle=detalle)
                creadas += 1
            elif ubicacion.detalle != detalle:
                ubicacion.detalle = detalle
                ubicacion.save(update_fields=['detalle'])
                actualizadas += 1
        self.stdout.write(self.style.SUCCESS(
            f"Listo: {creadas} ubicaciones creadas, {actualizadas} actualizadas "
            f"({len(UBICACIONES)} en total)."))